use bus_gateway::Caller;
use sdk::Refusal;
use sdk::generated::{editor, net, process, secrets, service, settings, update};

/// Generated by capgen: one provider per capability namespace, each answering its
/// namespace's calls for the plugin the gateway bound.
pub struct Providers<'p> {
    pub editor: &'p dyn editor::Provide,
    pub net: &'p dyn net::Provide,
    pub process: &'p dyn process::Provide,
    pub secrets: &'p dyn secrets::Provide,
    pub service: &'p dyn service::Provide,
    pub settings: &'p dyn settings::Provide,
    pub update: &'p dyn update::Provide,
}

/// Generated by capgen: the host one plugin calls the SDK with. It holds the
/// gateway's caller for that plugin and the providers; its fields are private, so a
/// plugin can neither build one for another id nor reach a provider.
pub struct Bound<'g, 'p> {
    caller: Caller<'g>,
    providers: &'p Providers<'p>,
}

impl<'g, 'p> Bound<'g, 'p> {
    /// Binds the providers to the caller the gateway bound. Inputs: the caller and the
    /// providers. Output: the host.
    pub fn new(caller: Caller<'g>, providers: &'p Providers<'p>) -> Self {
        Self { caller, providers }
    }
}

