    /// Inputs: the call's inputs. Output: its result or the refusal.
    fn editor_spawn(&self, launch: sdk::generated::editor::EditorLaunch) -> Result<u32, Refusal> {
        self.caller.call(
            &editor::SPAWN,
            launch,
            editor::check_spawn_input,
            |launch| self.providers.editor.spawn(self.caller.plugin(), launch),
            editor::check_spawn_output,
        )
    }

